# area: context_managers
# hypothesis: With __exit__ annotated to return bool, checkers must assume the block can swallow exceptions, so a function whose only return sits inside the with-block has no return on the fall-through path; with __exit__ returning None they accept it.
from typing import reveal_type


class Swallow:
    def __enter__(self) -> int:
        return 3

    def __exit__(self, *args: object) -> bool:
        return True


class Plain:
    def __enter__(self) -> int:
        return 4

    def __exit__(self, *args: object) -> None:
        return None


def via_swallow() -> int:  # expect-error: missing return on fall-through
    with Swallow() as n:
        return n + 1


def via_plain() -> int:
    with Plain() as n:
        return n + 1


def raises_in_block() -> int:
    with Swallow():
        raise ValueError('gone')
    return 99  # reached only because Swallow suppresses the error


print(via_swallow(), via_plain())
reveal_type(via_plain())
print(raises_in_block())
